1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
2	import { useNavigate } from "react-router";
3	import { Button } from "@/presentation/components/ui/button";
4	import type { PlayGameUseCase } from "../../application/use-cases/PlayGameUseCase";
5	import type {
6		GameCardPool,
7		GameInputMode,
8		GameItem,
9		GameRatingRecord,
10		GameRoundSummary as GameRoundSummaryData,
11	} from "../../domain/game/types";
12	import type { RecallRating } from "../../domain/shared/types";
13	import { SectionHeader } from "../components/atoms/SectionHeader";
14	import { GameHistoryList } from "../components/molecules/GameHistoryList";
15	import { GameRoundSummary } from "../components/organisms/GameRoundSummary";
16	import { SymbolDictationChallenge } from "../components/organisms/SymbolDictationChallenge";
17	import { SymbolReadingChallenge } from "../components/organisms/SymbolReadingChallenge";
18	import { WordDictationChallenge } from "../components/organisms/WordDictationChallenge";
19	import { WordProductionChallenge } from "../components/organisms/WordProductionChallenge";
20	import { useApp } from "../hooks/useApp";
21	
22	type GamePhase = "setup" | "playing" | "summary";
23	
24	/**
25	 * The setup screen's three choices, mapping to `GameCardPool` combinations
26	 * — `CardPool` values stay `"script"`/`"vocab"` everywhere below the UI
27	 * layer (see CONTEXT.md).
28	 */
29	type PoolChoice = "symbols" | "words" | "mix";
30	
31	const POOL_CHOICE_POOLS: Record<PoolChoice, readonly GameCardPool[]> = {
32		symbols: ["script"],
33		words: ["vocab"],
34		mix: ["script", "vocab"],
35	};
36	
37	const POOL_CHOICE_LABELS: Record<PoolChoice, string> = {
38		symbols: "Symbols",
39		words: "Words",
40		mix: "Mix",
41	};
42	
43	/**
44	 * The least surprising default for anyone who has only used this feature
45	 * since phase 1 — a repeat player's setup screen doesn't silently start
46	 * offering words until they choose to.
47	 */
48	const DEFAULT_POOL_CHOICE: PoolChoice = "symbols";
49	
50	const EMPTY_POOL_MESSAGES: Record<PoolChoice, string> = {
51		symbols: "No symbols to practice yet — complete a script lesson first.",
52		words: "No words to practice yet — complete a vocabulary lesson first.",
53		mix: "No items to practice yet — complete a script or vocabulary lesson first.",
54	};
55	
56	const DEFAULT_ITEM_COUNT = 10;
57	
58	/**
59	 * Selection is a pure function, so asking for every item is a side-effect-
60	 * free way to learn how many are eligible — the use case exposes no
61	 * separate count query.
62	 */
63	function countEligibleItems(
64		game: PlayGameUseCase,
65		pools: readonly GameCardPool[],
66	): number {
67		return game.startRound({
68			pools,
69			itemCount: Number.MAX_SAFE_INTEGER,
70			prioritizeWeakItems: false,
71			inputMode: "draw",
72		}).length;
73	}
74	
75	/**
76	 * A self-graded practice round over introduced symbols. The page owns all
77	 * round state (`items`/`ratings`/`currentIndex`) and threads it through
78	 * `PlayGameUseCase`'s pure functions — the use case is a long-lived
79	 * singleton and must never hold a round.
80	 *
81	 * Deliberately reads only `game` from `useApp()`: no `refresh()`, no
82	 * `checkAchievements`, nothing that could write the SRS blob. A practice
83	 * round must leave `thai-srs-state` byte-identical.
84	 */
85	export function GamePage() {
86		const { game } = useApp();
87		const navigate = useNavigate();
88	
89		const [phase, setPhase] = useState<GamePhase>("setup");
90		const [poolChoice, setPoolChoice] = useState<PoolChoice>(DEFAULT_POOL_CHOICE);
91		const [inputMode, setInputMode] = useState<GameInputMode>("draw");
92		const [items, setItems] = useState<GameItem[]>([]);
93		const [ratings, setRatings] = useState<GameRatingRecord[]>([]);
94		const [currentIndex, setCurrentIndex] = useState(0);
95		const [summary, setSummary] = useState<GameRoundSummaryData | null>(null);
96		// Guards against a rating landing twice for one item (a stray global
97		// keypress on top of a click) advancing past the next item unseen.
98		const ratedIndexRef = useRef(-1);
99	
100		const pools = POOL_CHOICE_POOLS[poolChoice];
101	
102		const eligibleCount = useMemo(
103			() => (phase === "setup" ? countEligibleItems(game, pools) : 0),
104			[game, phase, pools],
105		);
106		const [countInput, setCountInput] = useState<string>(() =>
107			eligibleCount > 0
108				? String(Math.min(DEFAULT_ITEM_COUNT, eligibleCount))
109				: "",
110		);
111		// The eligible count is pool-dependent — switching pools can make a
112		// previously-typed count invalid without ever telling the learner why.
113		// biome-ignore lint/correctness/useExhaustiveDependencies: resets only when the chosen pool changes, never on every eligibleCount-affecting render
114		useEffect(() => {
115			setCountInput(
116				eligibleCount > 0
117					? String(Math.min(DEFAULT_ITEM_COUNT, eligibleCount))
118					: "",
119			);
120		}, [poolChoice]);
121		const history = useMemo(
122			() => (phase === "setup" ? game.getHistory() : null),
123			[game, phase],
124		);
125	
126		// `Number("")` is 0, which the >= 1 rule already rejects.
127		const parsedCount = Number(countInput);
128		const countValid =
129			Number.isInteger(parsedCount) &&
130			parsedCount >= 1 &&
131			parsedCount <= eligibleCount;
132	
133		const handleStart = useCallback(() => {
134			const roundItems = game.startRound({
135				pools,
136				itemCount: parsedCount,
137				prioritizeWeakItems: false,
138				inputMode,
139			});
140			if (roundItems.length === 0) return;
141			setItems(roundItems);
142			setRatings([]);
143			setCurrentIndex(0);
144			setSummary(null);
145			ratedIndexRef.current = -1;
146			setPhase("playing");
147		}, [game, pools, parsedCount, inputMode]);
148	
149		const handleRate = useCallback(
150			(rating: RecallRating) => {
151				if (ratedIndexRef.current >= currentIndex) return;
152				ratedIndexRef.current = currentIndex;
153	
154				const nextRatings = game.recordRating(
155					items,
156					ratings,
157					currentIndex,
158					rating,
159				);
160				setRatings(nextRatings);
161	
162				if (currentIndex + 1 < items.length) {
163					setCurrentIndex(currentIndex + 1);
164					return;
165				}
166	
167				const roundSummary = game.finishRound(nextRatings);
168				game.saveHistory({ pools, itemCount: items.length }, roundSummary);
169				setSummary(roundSummary);
170				setPhase("summary");
171			},
172			[game, items, ratings, currentIndex, pools],
173		);
174	
175		if (phase === "playing") {
176			const item = items[currentIndex];
177			if (!item) return null;
178	
179			// The page dispatches by `kind` then `challengeDirection`; each
180			// organism receives a single-kind, single-direction prop and never
181			// inspects `GameItem`'s union tag itself (see task 2.3's
182			// architectural decision).
183			const challenge =
184				item.kind === "symbol" ? (
185					item.challengeDirection === "dictation" ? (
186						<SymbolDictationChallenge
187							item={item}
188							inputMode={inputMode}
189							onRate={handleRate}
190						/>
191					) : (
192						<SymbolReadingChallenge item={item} onRate={handleRate} />
193					)
194				) : item.challengeDirection === "dictationTranslate" ? (
195					<WordDictationChallenge
196						item={item}
197						inputMode={inputMode}
198						onRate={handleRate}
199					/>
200				) : (
201					<WordProductionChallenge
202						item={item}
203						inputMode={inputMode}
204						onRate={handleRate}
205					/>
206				);
207	
208			return (
209				<div>
210					<div className="mb-4 flex items-center justify-between">
211						<span
212							className="text-sm font-semibold"
213							style={{ color: "var(--color-text)" }}
214						>
215							Practice Round
216						</span>
217						<span
218							className="text-sm"
219							style={{ color: "var(--color-text-muted)" }}
220						>
221							{currentIndex + 1} / {items.length}
222						</span>
223						<button
224							type="button"
225							onClick={() => navigate("/")}
226							className="text-lg leading-none"
227							style={{ color: "var(--color-text-muted)" }}
228							aria-label="End round"
229							title="End round"
230						>
231							✕
232						</button>
233					</div>
234	
235					{challenge}
236				</div>
237			);
238		}
239	
240		if (phase === "summary" && summary) {
241			return (
242				<div className="space-y-6 py-8">
243					<GameRoundSummary summary={summary} itemCount={items.length} />
244					<div className="space-y-3">
245						<Button className="w-full" onClick={() => setPhase("setup")}>
246							Play Again
247						</Button>
248						<Button
249							variant="outline"
250							className="w-full"
251							onClick={() => navigate("/")}
252						>
253							Go to Dashboard
254						</Button>
255					</div>
256				</div>
257			);
258		}
259	
260		return (
261			<div className="space-y-6 py-4">
262				<div>
263					<h1
264						className="text-2xl font-semibold"
265						style={{ color: "var(--color-text)" }}
266					>
267						Practice Game
268					</h1>
269					<p
270						className="text-sm mt-1"
271						style={{ color: "var(--color-text-muted)" }}
272					>
273						Self-graded drilling over your introduced symbols — it never changes
274						your review schedule.
275					</p>
276				</div>
277	
278				<fieldset
279					className="rounded-xl p-4"
280					style={{
281						border: "1px solid var(--color-border)",
282						background: "var(--color-surface)",
283					}}
284				>
285					<legend
286						className="text-sm font-semibold mb-1"
287						style={{ color: "var(--color-text)" }}
288					>
289						Practice pool
290					</legend>
291					<div className="flex gap-4">
292						{(Object.keys(POOL_CHOICE_POOLS) as PoolChoice[]).map((choice) => (
293							<span key={choice} className="flex items-center gap-2">
294								<input
295									id={`game-pool-${choice}`}
296									type="radio"
297									name="game-pool-choice"
298									checked={poolChoice === choice}
299									onChange={() => setPoolChoice(choice)}
300								/>
301								<label
302									htmlFor={`game-pool-${choice}`}
303									className="text-sm"
304									style={{ color: "var(--color-text)" }}
305								>
306									{POOL_CHOICE_LABELS[choice]}
307								</label>
308							</span>
309						))}
310					</div>
311				</fieldset>
312	
313				{eligibleCount === 0 ? (
314					<p
315						className="rounded-xl p-4 text-sm"
316						style={{
317							background: "var(--color-surface-2)",
318							color: "var(--color-text-muted)",
319						}}
320					>
321						{EMPTY_POOL_MESSAGES[poolChoice]}
322					</p>
323				) : (
324					<div
325						className="rounded-xl p-4 space-y-4"
326						style={{
327							border: "1px solid var(--color-border)",
328							background: "var(--color-surface)",
329						}}
330					>
331						<div>
332							<label
333								htmlFor="game-item-count"
334								className="block text-sm font-semibold mb-1"
335								style={{ color: "var(--color-text)" }}
336							>
337								Items per round
338							</label>
339							<input
340								id="game-item-count"
341								type="number"
342								min={1}
343								max={eligibleCount}
344								step={1}
345								value={countInput}
346								onChange={(e) => setCountInput(e.target.value)}
347								className="w-full rounded-xl p-3"
348								style={{
349									border: "1px solid var(--color-border)",
350									background: "var(--color-surface-2)",
351									color: "var(--color-text)",
352								}}
353							/>
354							<p
355								className="text-xs mt-1"
356								style={{ color: "var(--color-text-muted)" }}
357							>
358								Whole number from 1 to {eligibleCount}
359							</p>
360						</div>
361	
362						<fieldset>
363							<legend
364								className="text-sm font-semibold mb-1"
365								style={{ color: "var(--color-text)" }}
366							>
367								Input mode
368							</legend>
369							<div className="flex gap-4">
370								<span className="flex items-center gap-2">
371									<input
372										id="game-input-draw"
373										type="radio"
374										name="game-input-mode"
375										checked={inputMode === "draw"}
376										onChange={() => setInputMode("draw")}
377									/>
378									<label
379										htmlFor="game-input-draw"
380										className="text-sm"
381										style={{ color: "var(--color-text)" }}
382									>
383										Draw on canvas
384									</label>
385								</span>
386								<span className="flex items-center gap-2">
387									<input
388										id="game-input-paper"
389										type="radio"
390										name="game-input-mode"
391										checked={inputMode === "paper"}
392										onChange={() => setInputMode("paper")}
393									/>
394									<label
395										htmlFor="game-input-paper"
396										className="text-sm"
397										style={{ color: "var(--color-text)" }}
398									>
399										Write on paper
400									</label>
401								</span>
402							</div>
403						</fieldset>
404	
405						<Button
406							className="w-full"
407							disabled={!countValid}
408							onClick={handleStart}
409						>
410							Start Round
411						</Button>
412					</div>
413				)}
414	
415				{history && (
416					<div>
417						<SectionHeader className="mb-3">Recent Rounds</SectionHeader>
418						<GameHistoryList result={history} />
419					</div>
420				)}
421			</div>
422		);
423	}
